ory", "sensitivity_level": "health", "options": ["cancer_close_relative", "early_menopause", "blood_clots", "heart_attack_young", "diabetes", "osteoporosis", "thyroid_disease", "something_else", "no_clinician_mentioned", "dont_know_family_history", "prefer_not_to_say"], "option_labels": {"cancer_close_relative": "Breast, ovarian, or uterine cancer in a close relative", "early_menopause": "Very early menopause", "blood_clots": "Blood clots or a clotting condition", "heart_attack_young": "Heart attack or stroke at a young age", "diabetes": "Diabetes", "osteoporosis": "Osteoporosis", "thyroid_disease": "Thyroid disease", "something_else": "Something else", "no_clinician_mentioned": "No clinician has mentioned anything like this", "dont_know_family_history": "I do not know my family health history", "prefer_not_to_say": "Prefer not to answer"}, "required": true, "label": "Are there health patterns in your family that a clinician has told you to keep in mind?"}, {"field_id": "CYC_HEALTH_BEHAVIOR", "format": "single_choice", "profile_path": "cycle.health_behavior", "options": ["routine_visits", "appointment_when_symptoms", "put_off_appointments", "hard_to_find_trust", "bad_experience_avoid", "not_sure_checkups", "prefer_not_to_say"], "option_labels": {"routine_visits": "I keep up with routine visits and reach out when something changes", "appointment_when_symptoms": "I make an appointment when symptoms start interfering with life", "put_off_appointments": "I often put off appointments until the last minute", "hard_to_find_trust": "It is hard to find a clinician I trust", "bad_experience_avoid": "I have had a bad experience and tend to avoid care", "not_sure_checkups": "I am not sure what checkups I need or how often", "prefer_not_to_say": "Prefer not to answer"}, "required": true, "label": "How do you usually take care of your reproductive health?"}, {"field_id": "CYC_OCCUPATION", "format": "single_choice", "profile_path": "person.occupation_category", "options": ["work",