le right now", "not_sure": "I am not sure which option is right for me", "prefer_not_to_say": "Prefer not to answer"}, "label": "How are you currently handling pregnancy and STI protection?"}, {"field_id": "CYC_BEHAVIOR", "format": "paired_choice", "profile_path": "person.behavior", "rows": [{"row_id": "planning", "options": ["plan_ahead", "decide_as_i_go"], "option_labels": {"plan_ahead": "Plan ahead", "decide_as_i_go": "Decide as I go"}}, {"row_id": "depth", "options": ["action_first", "explain_first"], "option_labels": {"action_first": "Give me the action first", "explain_first": "Explain it first"}}, {"row_id": "length", "options": ["brief", "detailed"], "option_labels": {"brief": "Brief", "detailed": "Detailed"}}, {"row_id": "reminders", "options": ["gentle_reminders", "only_when_open_app"], "option_labels": {"gentle_reminders": "Gentle reminders", "only_when_open_app": "Only when I open the app"}}, {"row_id": "steps", "options": ["one_main_step", "few_steps_for_day"], "option_labels": {"one_main_step": "One main step", "few_steps_for_day": "A few steps for the day"}}], "required": true, "label": "How do you prefer to receive support?"}, {"field_id": "CYC_TONE", "format": "single_choice", "profile_path": "person.communication.tone", "options": ["gentle", "friendly", "close_friend", "direct"], "option_labels": {"gentle": "Gentle - soft and careful, with no jokes", "friendly": "Friendly - natural and easy, with occasional light humor", "close_friend": "Like someone who knows me well - informal, conversational, and okay with jokes", "direct": "Direct - brief, honest, and never overly sweet"}, "required": true, "label": "How can Momna talk with you?"}]}]}'::jsonb, 'draft')
