  ('pregnancy', 'pregnancy', 2, 'ru', '{"sections": [{"id": "pregnancy", "questions": [{"field_id": "PRG_DATES_METHOD", "format": "single_choice", "required": true, "options": ["gestational_age", "edd", "unknown"], "option_labels": {"gestational_age": "Знаю срок в неделях", "edd": "Знаю предполагаемую дату родов", "unknown": "Пока не знаю"}, "label": "Как тебе удобнее указать срок беременности?", "hint": "Выбери самый простой для тебя способ рассказать о беременности."}, {"field_id": "PRG_GESTATIONAL_WEEKS", "format": "number", "profile_path": "pregnancy.gestational_weeks", "show_if": {"field_id": "PRG_DATES_METHOD", "in": ["gestational_age"]}, "min": 1, "max": 45, "required": true, "label": "На каком ты сроке?"}, {"field_id": "PRG_EDD", "format": "date", "profile_path": "pregnancy.edd", "show_if": {"field_id": "PRG_DATES_METHOD", "in": ["edd"]}, "date_constraint": "future_or_today", "min_future_days": 7, "max_future_days": 294, "required": true, "label": "Какая у тебя предполагаемая дата родов?"}, {"field_id": "PRG_LMP", "format": "date", "profile_path": "pregnancy.lmp", "show_if": {"field_id": "PRG_DATES_METHOD", "in": ["unknown"]}, "date_constraint": "past_or_today", "max_past_days": 308, "min_past_days": 14, "extra_option": "i_do_not_remember", "required": true, "label": "Когда начались последние месячные?", "hint": "Это поможет автоматически рассчитать предполагаемую дату родов.", "extra_option_label": "Я не помню"}, {"field_id": "PRG_MULTIPLES", "format": "single_choice", "profile_path": "pregnancy.multiples", "options": ["one_baby", "twins", "triplets", "more_than_three", "unknown", "prefer_not_to_say"], "option_labels": {"one_baby": "Один ребёнок", "twins": "Двойня", "triplets": "Тройня", "more_than_three": "Больше трёх", "unknown": "Пока не знаю", "prefer_not_to_say": "Не хочу отвечать"}, "required": true, "label": "Сколько детей ты ждёшь?"}, {"field_id": "PRG_GOALS", "format": "multi_choice", "max_select": 3, "profile_path": "pregnancy.goals", "options": [